/* Halo web app demo backend.
 *
 * Halo serves the web app itself at http://halo.local:8080. When the same page is opened
 * anywhere else (GitHub Pages, or with ?demo in the URL) this file answers the /api/ calls
 * in the browser instead, with sample bottles and drinks, so the app can be tried before
 * the hardware exists. Nothing leaves the browser and changes reset on reload.
 * Generated by scripts/build_demo.py from the sample data; edit the template, not demo.js.
 */
(() => {
  const on = location.hostname.endsWith("github.io") || new URLSearchParams(location.search).has("demo");
  if (!on) return;

  const SEED = {"bottles":[{"abv":40,"capacity_ml":750.0,"color":"#cfe3dc","density":0.95,"level":0.64,"name":"Gin","remaining_ml":480,"slot":1},{"abv":40,"capacity_ml":750.0,"color":"#f2e9d8","density":0.95,"level":0.81,"name":"White Rum","remaining_ml":608,"slot":2},{"abv":45,"capacity_ml":750.0,"color":"#c47a2c","density":0.94,"level":0.47,"name":"Bourbon","remaining_ml":352,"slot":3},{"abv":40,"capacity_ml":750.0,"color":"#e9e4c9","density":0.95,"level":0.9,"name":"Tequila Blanco","remaining_ml":675,"slot":4},{"abv":30,"capacity_ml":750.0,"color":"#f2a33a","density":1.05,"level":0.72,"name":"Orange Liqueur","remaining_ml":540,"slot":5},{"abv":0,"capacity_ml":750.0,"color":"#b8d86b","density":1.03,"level":0.11,"name":"Lime Juice","remaining_ml":82,"slot":6},{"abv":0,"capacity_ml":750.0,"color":"#f4ecd2","density":1.3,"level":0.55,"name":"Simple Syrup","remaining_ml":413,"slot":7},{"abv":0,"capacity_ml":750.0,"color":"#d9eef7","density":1.0,"level":0.38,"name":"Soda Water","remaining_ml":285,"slot":8}],"recipes":[{"name":"Garden Highball","ingredients":[{"bottle":"Gin","parts":1.5},{"bottle":"Lime Juice","parts":0.5},{"bottle":"Simple Syrup","parts":0.4},{"bottle":"Soda Water","parts":3.0}],"description":"Gin, lime and bubbles. Crisp and very easy to like.","garnish":"cucumber ribbon","glass":"highball","color":"#d6ecd9","created_by":"you","tags":["refreshing"],"favorite":false},{"name":"Daiquiri","ingredients":[{"bottle":"White Rum","parts":2.0},{"bottle":"Lime Juice","parts":1.0},{"bottle":"Simple Syrup","parts":0.75}],"description":"The classic three-ingredient rum sour. Bright, clean, tart.","garnish":"lime wheel","glass":"coupe","color":"#eef1cf","created_by":"you","tags":["sour","classic"],"favorite":true},{"name":"Margarita","ingredients":[{"bottle":"Tequila Blanco","parts":2.0},{"bottle":"Orange Liqueur","parts":1.0},{"bottle":"Lime Juice","parts":1.0}],"description":"Tequila, orange and lime, built straight. Add salt and ice.","garnish":"salt rim","glass":"rocks","color":"#e6e59a","created_by":"you","tags":["sour","classic"],"favorite":false},{"name":"Bourbon Smash","ingredients":[{"bottle":"Bourbon","parts":2.0},{"bottle":"Orange Liqueur","parts":0.5},{"bottle":"Simple Syrup","parts":0.25}],"description":"Bourbon softened with orange and a touch of sugar.","garnish":"orange peel","glass":"rocks","color":"#c27a31","created_by":"you","tags":["strong"],"favorite":false},{"name":"Rum Fizz","ingredients":[{"bottle":"White Rum","parts":1.5},{"bottle":"Lime Juice","parts":0.75},{"bottle":"Simple Syrup","parts":0.5},{"bottle":"Soda Water","parts":3.0}],"description":"Light rum and lime topped long with soda.","garnish":"mint","glass":"highball","color":"#e8f3e6","created_by":"you","tags":["refreshing","low"],"favorite":false},{"name":"Ember Old Fashioned","ingredients":[{"bottle":"Bourbon","parts":2.0},{"bottle":"Simple Syrup","parts":0.25},{"bottle":"Orange Liqueur","parts":0.25}],"description":"Bourbon softened with a little orange liqueur in place of bitters. Warm, round and slow.","garnish":"orange peel","glass":"rocks","color":"#c47a2c","created_by":"claude","tags":["strong","classic"],"favorite":true},{"name":"Paloma Spritz","ingredients":[{"bottle":"Tequila Blanco","parts":1.5},{"bottle":"Lime Juice","parts":0.5},{"bottle":"Simple Syrup","parts":0.4},{"bottle":"Soda Water","parts":3.0},{"bottle":"Grapefruit Soda","parts":1.0}],"description":"Tequila and lime lengthened with soda. Load grapefruit soda to make it.","garnish":"salt rim","glass":"highball","color":"#f4c7b0","created_by":"claude","tags":["refreshing"],"favorite":false}],"history":[{"time":1793901697,"drink":"Rum Fizz","size":"single","strength":"normal","by":"phone","state":"done","report":[{"bottle":"White Rum","ml":15.4,"target_g":14.6,"poured_g":14.6},{"bottle":"Lime Juice","ml":7.7,"target_g":7.9,"poured_g":7.9},{"bottle":"Simple Syrup","ml":5.1,"target_g":6.7,"poured_g":6.7},{"bottle":"Soda Water","ml":30.8,"target_g":30.8,"poured_g":30.8}]},{"time":1793988097,"drink":"Margarita","size":"single","strength":"normal","by":"phone","state":"done","report":[{"bottle":"Tequila Blanco","ml":29.5,"target_g":28.0,"poured_g":28.0},{"bottle":"Orange Liqueur","ml":14.8,"target_g":15.5,"poured_g":15.5},{"bottle":"Lime Juice","ml":14.8,"target_g":15.2,"poured_g":15.2}]},{"time":1794074497,"drink":"Ember Old Fashioned","size":"single","strength":"normal","by":"phone","state":"done","report":[{"bottle":"Bourbon","ml":47.2,"target_g":44.4,"poured_g":44.4},{"bottle":"Simple Syrup","ml":5.9,"target_g":7.7,"poured_g":7.7},{"bottle":"Orange Liqueur","ml":5.9,"target_g":6.2,"poured_g":6.2}]},{"time":1794160897,"drink":"Daiquiri","size":"single","strength":"normal","by":"phone","state":"done","report":[{"bottle":"White Rum","ml":31.5,"target_g":29.9,"poured_g":29.9},{"bottle":"Lime Juice","ml":15.7,"target_g":16.2,"poured_g":16.2},{"bottle":"Simple Syrup","ml":11.8,"target_g":15.3,"poured_g":15.3}]},{"time":1794247297,"drink":"Garden Highball","size":"single","strength":"normal","by":"phone","state":"done","report":[{"bottle":"Gin","ml":16.4,"target_g":15.6,"poured_g":15.6},{"bottle":"Lime Juice","ml":5.5,"target_g":5.6,"poured_g":5.6},{"bottle":"Simple Syrup","ml":4.4,"target_g":5.7,"poured_g":5.7},{"bottle":"Soda Water","ml":32.8,"target_g":32.8,"poured_g":32.8}]},{"time":1794316417,"drink":"Daiquiri","size":"single","strength":"normal","by":"phone","state":"done","report":[{"bottle":"White Rum","ml":31.5,"target_g":29.9,"poured_g":29.9},{"bottle":"Lime Juice","ml":15.7,"target_g":16.2,"poured_g":16.2},{"bottle":"Simple Syrup","ml":11.8,"target_g":15.3,"poured_g":15.3}]},{"time":1794385537,"drink":"Margarita","size":"single","strength":"normal","by":"phone","state":"done","report":[{"bottle":"Tequila Blanco","ml":29.5,"target_g":28.0,"poured_g":28.0},{"bottle":"Orange Liqueur","ml":14.8,"target_g":15.5,"poured_g":15.5},{"bottle":"Lime Juice","ml":14.8,"target_g":15.2,"poured_g":15.2}]}],"prefs":{"led_brightness":0.4,"ambient":true,"default_strength":"normal","single_oz":null,"double_oz":null,"low_level_pct":15,"voice_enabled":true},"moods":["surprise","refreshing","strong","sweet","sour","low","classic"],"strengths":["light","normal","strong"]};
  const STRENGTH = {light: 0.7, normal: 1.0, strong: 1.35};
  const SPIRIT_ABV = 15, ML_PER_OZ = 29.57;
  const clone = o => JSON.parse(JSON.stringify(o));
  const db = {bottles: clone(SEED.bottles), recipes: clone(SEED.recipes), history: clone(SEED.history),
              prefs: clone(SEED.prefs), party: {active: false, theme: "", drinks: []}, status: idle()};
  let timer = null;

  function idle() {
    return {state: "idle", drink: "", size: "single", strength: "normal", by: "", step: "", step_index: -1,
            color: "", fraction: 0, poured_g: 0, target_g: 0, speed: 0, message: "", segments: [], report: []};
  }
  class ApiError extends Error {}
  const fail = (msg) => { throw new ApiError(msg); };
  const find = name => db.bottles.find(b => b.name && b.name.toLowerCase() === String(name).toLowerCase());
  const recipe = name => db.recipes.find(r => r.name.toLowerCase() === String(name).toLowerCase());
  const level = b => { b.level = b.capacity_ml ? Math.max(0, Math.min(1, b.remaining_ml / b.capacity_ml)) : 0; return b; };

  function weighted(r, strength = "normal") {
    const k = STRENGTH[strength] ?? 1;
    return r.ingredients.map(i => { const b = find(i.bottle); return [i, i.parts * (b && b.abv >= SPIRIT_ABV ? k : 1)]; });
  }
  function recipeJson(r) {
    const missing = r.ingredients.filter(i => !find(i.bottle)).map(i => i.bottle);
    let abv = null;
    if (!missing.length) {
      const w = weighted(r), parts = w.reduce((a, [, x]) => a + x, 0) || 1;
      abv = Math.round(w.reduce((a, [i, x]) => a + find(i.bottle).abv * x, 0) / parts * 10) / 10;
    }
    return {...clone(r), available: !missing.length, missing, abv,
            colors: r.ingredients.map(i => (find(i.bottle) || {}).color || "#555"),
            in_party: db.party.active && db.party.drinks.some(n => n.toLowerCase() === r.name.toLowerCase())};
  }
  const sizes = () => ({single: Math.round((db.prefs.single_oz || 2) * ML_PER_OZ),
                        double: Math.round((db.prefs.double_oz || 4) * ML_PER_OZ)});
  const low = () => db.bottles.filter(b => b.name && b.level * 100 < db.prefs.low_level_pct).map(b => b.slot);

  function state() {
    return {bottles: db.bottles.map(level), recipes: db.recipes.map(recipeJson), party: db.party, prefs: db.prefs,
            low: low(), moods: SEED.moods, strengths: SEED.strengths, sizes: sizes(), status: db.status,
            ring: null, gate: null, mock: true, demo: true};
  }

  function stats() {
    const done = db.history.filter(h => h.state === "done"), drinks = {}, byBottle = {};
    let total = 0;
    for (const h of done) {
      drinks[h.drink] = (drinks[h.drink] || 0) + 1;
      for (const r of h.report || []) { byBottle[r.bottle] = (byBottle[r.bottle] || 0) + (r.ml || 0); total += r.ml || 0; }
    }
    const week = Date.now() / 1000 - 7 * 86400;
    return {pours: done.length, this_week: done.filter(h => h.time > week).length, total_ml: Math.round(total),
            top_drinks: Object.entries(drinks).sort((a, b) => b[1] - a[1]).slice(0, 8),
            by_bottle: Object.entries(byBottle).map(([k, v]) => [k, Math.round(v)]).sort((a, b) => b[1] - a[1]),
            recent: db.history.slice(-12).reverse()};
  }

  /* ---------------------------------------------------------------- pouring, simulated */
  function startPour(r, size, strength, by) {
    if (!["idle", "done", "error", "cancelled"].includes(db.status.state)) fail("Halo is already pouring");
    const missing = r.ingredients.filter(i => !find(i.bottle)).map(i => i.bottle);
    if (missing.length) fail(`Not loaded: ${missing.join(", ")}`);
    strength = STRENGTH[strength] ? strength : db.prefs.default_strength;
    size = size === "double" ? "double" : "single";
    const total = sizes()[size], w = weighted(r, strength), parts = w.reduce((a, [, x]) => a + x, 0);
    const steps = w.map(([i, x]) => { const b = find(i.bottle), ml = total * x / parts;
      return {bottle: b.name, color: b.color, ml, grams: ml * b.density, density: b.density}; })
      .sort((a, b) => b.density - a.density);
    for (const s of steps) if (find(s.bottle).remaining_ml < s.ml) fail(`${s.bottle} is too low for this drink`);
    const target = steps.reduce((a, s) => a + s.grams, 0);
    db.status = {...idle(), state: "waiting_for_glass", drink: r.name, size, strength, by,
                 message: "Place a glass on the halo", target_g: Math.round(target * 10) / 10,
                 segments: steps.map(s => ({bottle: s.bottle, color: s.color, target_g: Math.round(s.grams * 10) / 10}))};
    db.pour = {steps, target, r, idx: 0, done: 0, got: 0};
  }
  function glass() {
    if (db.status.state !== "waiting_for_glass") return;
    clearInterval(timer);
    timer = setInterval(tick, 120);
  }
  function tick() {
    const p = db.pour, s = p.steps[p.idx], st = db.status;
    const left = s.grams - p.got, speed = left < 8 ? Math.max(0.35, left / 8) : 1;
    p.got = Math.min(s.grams, p.got + 1.6 * speed);
    Object.assign(st, {state: "pouring", step: s.bottle, step_index: p.idx, color: s.color, speed,
                       message: `Pouring ${s.bottle}`, poured_g: Math.round((p.done + p.got) * 10) / 10,
                       fraction: Math.round((p.done + p.got) / p.target * 1000) / 1000});
    if (p.got >= s.grams - 0.01) {
      st.report.push({bottle: s.bottle, target_g: Math.round(s.grams * 10) / 10, poured_g: Math.round(s.grams * 10) / 10,
                      ml: Math.round(s.ml * 10) / 10});
      const b = find(s.bottle); b.remaining_ml = Math.max(0, b.remaining_ml - s.ml); level(b);
      p.done += s.grams; p.got = 0; p.idx++;
      if (p.idx >= p.steps.length) finish("done", `Enjoy. ${p.r.garnish ? p.r.garnish[0].toUpperCase() + p.r.garnish.slice(1) + " to finish." : ""}`.trim());
    }
  }
  function finish(state, message) {
    clearInterval(timer);
    Object.assign(db.status, {state, message, speed: 0, step: state === "done" ? "" : db.status.step,
                              fraction: state === "done" ? 1 : db.status.fraction});
    db.history.push({time: Date.now() / 1000, drink: db.status.drink, size: db.status.size, strength: db.status.strength,
                     by: db.status.by, state, report: clone(db.status.report)});
  }

  /* ---------------------------------------------------------------- bartender, canned */
  const NAMES = {surprise: ["Night Garden", "Copper Hour", "Low Lantern"], refreshing: ["Porch Light", "Cold Front"],
                 strong: ["Slow Burn", "Iron Gate"], sweet: ["Honey Hour", "Velvet Step"], sour: ["Sharp Turn", "Green Flash"],
                 low: ["Long Afternoon", "Soft Landing"], classic: ["House Sour", "Gatekeeper"]};
  function invent(request) {
    const mood = Object.keys(NAMES).find(m => String(request).toLowerCase().includes(m)) || "surprise";
    const loaded = db.bottles.filter(b => b.name && b.remaining_ml > 30);
    const spirits = loaded.filter(b => b.abv >= SPIRIT_ABV && b.abv >= 30);
    const pick = a => a[Math.floor(Math.random() * a.length)];
    if (!spirits.length) fail("Load at least one spirit first");
    const base = pick(spirits), sour = loaded.find(b => /lime|lemon/i.test(b.name)),
          sweet = loaded.find(b => /syrup|liqueur/i.test(b.name) && b !== base), long = loaded.find(b => /soda|tonic|ginger/i.test(b.name));
    const ing = [{bottle: base.name, parts: mood === "strong" ? 2.25 : mood === "low" ? 1 : 1.75}];
    if (sour && mood !== "strong") ing.push({bottle: sour.name, parts: mood === "sour" ? 1 : 0.75});
    if (sweet) ing.push({bottle: sweet.name, parts: mood === "sweet" ? 0.75 : 0.5});
    const lengthen = long && ["refreshing", "low"].includes(mood);
    if (lengthen) ing.push({bottle: long.name, parts: mood === "low" ? 4 : 3});
    let name = pick(NAMES[mood]);
    if (recipe(name)) name += ` No. ${db.recipes.length + 1}`;
    return {name, ingredients: ing, garnish: sour ? "lime wheel" : "orange peel", glass: lengthen ? "highball" : "coupe",
            color: base.color, created_by: "claude", tags: [mood], favorite: false,
            description: `${base.name} built around "${request}". In this demo the drink comes from a simple template; on a real Halo, Claude writes it from your bottles.`};
  }

  /* ---------------------------------------------------------------- routes */
  async function handle(path, opts = {}) {
    await new Promise(r => setTimeout(r, path === "bartender" || path === "party" && opts.method === "POST" ? 900 : 60));
    const m = (opts.method || "GET").toUpperCase(), body = opts.body ? (typeof opts.body === "string" ? JSON.parse(opts.body) : opts.body) : {};
    const [a, b, c] = path.split("/").map(decodeURIComponent);
    if (a === "state") return state();
    if (a === "status") return db.status;
    if (a === "stats") return stats();
    if (a === "prefs") { if (m === "PUT") Object.assign(db.prefs, body); return db.prefs; }
    if (a === "bottles" && b === "swap") {
      const x = db.bottles[body.a - 1], y = db.bottles[body.b - 1];
      if (!x || !y || body.a === body.b) fail("pick two different slots");
      db.bottles[body.a - 1] = {...y, slot: body.a}; db.bottles[body.b - 1] = {...x, slot: body.b}; return {ok: true};
    }
    if (a === "bottles" && c === "refill") { const x = db.bottles[+b - 1]; x.remaining_ml = x.capacity_ml; return level(x); }
    if (a === "bottles" && m === "PUT") {
      const old = db.bottles[+b - 1]; if (!old) fail("slot must be 1-8");
      const name = String(body.name ?? old.name).trim(), cap = +(body.capacity_ml ?? old.capacity_ml) || 750;
      const nb = {slot: +b, name, abv: +(body.abv ?? old.abv) || 0, density: +(body.density ?? old.density) || 1,
                  color: body.color ?? old.color, capacity_ml: cap,
                  remaining_ml: Math.min(cap, body.remaining_ml ?? (name.toLowerCase() !== old.name.toLowerCase() ? cap : old.remaining_ml))};
      if ([nb.abv, nb.density, nb.capacity_ml].some(Number.isNaN)) fail("numbers please for ABV, density and sizes");
      db.bottles[+b - 1] = level(nb); return nb;
    }
    if (a === "bottles") return db.bottles.map(level);
    if (a === "recipes" && b === "export") return db.recipes.map(clone);
    if (a === "recipes" && b === "import") {
      let added = 0;
      for (const d of Array.isArray(body) ? body : []) if (d && d.name && Array.isArray(d.ingredients)) { add(d); added++; }
      return {added};
    }
    if (a === "recipes" && c === "favorite") { const r = recipe(b) || fail("unknown drink"); r.favorite = !r.favorite; return recipeJson(r); }
    if (a === "recipes" && m === "DELETE") { db.recipes = db.recipes.filter(r => r.name.toLowerCase() !== b.toLowerCase()); return {ok: true}; }
    if (a === "recipes" && m === "POST") {
      if (!String(body.name || "").trim() || !(body.ingredients || []).length) fail("a drink needs a name and at least one ingredient");
      return recipeJson(add(body));
    }
    if (a === "recipes") return db.recipes.map(recipeJson);
    if (a === "bartender") { const r = invent(body.request || "surprise"); if (body.save) add(r); return recipeJson(r); }
    if (a === "party" && m === "DELETE") { db.party = {active: false, theme: "", drinks: []}; return db.party; }
    if (a === "party" && m === "POST") {
      const theme = String(body.theme || "").trim();
      if (body.drinks && body.drinks.length) { db.party = {active: true, theme, drinks: body.drinks.map(String)}; return db.party; }
      if (!theme) fail("give the party a theme");
      const menu = [];
      for (const mood of ["refreshing", "sour", "strong", "sweet", "classic"].slice(0, body.count || 5)) {
        const r = invent(`${theme}, ${mood}`); r.description = `For "${theme}". ` + r.description; add(r); menu.push(r);
      }
      db.party = {active: true, theme, drinks: menu.map(r => r.name)};
      return {party: db.party, drinks: menu.map(recipeJson)};
    }
    if (a === "party") return db.party;
    if (a === "pour") {
      let r = recipe(body.drink || "");
      if (!r && body.request) { r = invent(body.request); add(r); }
      if (!r) fail("Unknown drink");
      startPour(r, body.size, body.strength, body.by || "web"); return {ok: true, drink: r.name};
    }
    if (a === "cancel") { if (!["idle", "done", "error", "cancelled"].includes(db.status.state)) finish("cancelled", "Cancelled"); return {ok: true}; }
    if (a === "dev" && b === "glass") { glass(); return {ok: true}; }
    if (a === "voice") fail("Voice orders come from Levi on a real Halo");
    if (a === "ring") return {ok: true};
    fail("not found");
  }
  function add(d) {
    const r = {name: String(d.name).trim(), ingredients: d.ingredients.map(i => ({bottle: String(i.bottle), parts: +i.parts || 1})),
               description: d.description || "", garnish: d.garnish || "", glass: d.glass || "", color: d.color || "#c9a46a",
               created_by: d.created_by || "you", tags: d.tags || [], favorite: !!d.favorite};
    const drop = new Set([r.name.toLowerCase(), String(d.replace || "").toLowerCase()]);
    db.recipes = db.recipes.filter(x => !drop.has(x.name.toLowerCase()));
    db.recipes.push(r);
    return r;
  }

  window.HaloDemo = {
    async handle(path, opts) {
      try { return await handle(path, opts); }
      catch (e) { if (e instanceof ApiError) throw new Error(e.message); throw e; }
    },
  };
})();
